def transform(grid):
    out = [row[:] for row in grid]
    # A fully empty row inherits the uniform color of its nonempty neighbors.
    for r, row in enumerate(grid):
        if all(v == 0 for v in row):
            neighbor_colors = []
            for rr in (r - 1, r + 1):
                if 0 <= rr < len(grid):
                    colors = {v for v in grid[rr] if v != 0}
                    if len(colors) == 1:
                        neighbor_colors.extend(colors)
            if neighbor_colors and len(set(neighbor_colors)) == 1:
                out[r] = [neighbor_colors[0]] * len(row)
    return out

