 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each colored diagonal (constant column-row) gives a value in one
    # position of the repeating diagonal color cycle.
    tracks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in tracks and tracks[d] != value:
                    raise ValueError('inconsistent diagonal')
                tracks[d] = value
    period = len(tracks)
    cycle = {}
    for d, value in tracks.items():
        residue = d % period
        if residue in cycle and cycle[residue] != value:
            raise ValueError('inconsistent cycle')
        cycle[residue] = value
    if len(cycle) != period:
        raise ValueError('incomplete cycle')
    return [[cycle[(c-r) % period] for c in range(w)] for r in range(h)]
